DO $publish$ DECLARE j jsonb := $expected$[{"language":"es","slug":"patatas-bravas-freidora-aire","public_path":"/patatas-bravas-freidora-aire","title":"Patatas bravas en freidora de aire con salsa casera","excerpt":"Patatas bravas doradas en freidora de aire, con salsa de pimentón y caldo sin tomate. Una tapa para compartir, con tiempos por tanda y picante ajustable.","summary":"Patatas bravas doradas en freidora de aire, con salsa de pimentón y caldo sin tomate. Una tapa para compartir, con tiempos por tanda y picante ajustable.","notes":"<p>Corta dados de 2 cm y usa una freidora de al menos 5 litros; si quedan amontonados, haz dos tandas y añade unos 25 minutos al total. La salsa lleva harina de trigo: contiene gluten. Usa caldo sin gluten y maicena solo con una adaptación de la salsa. No añadas el pimentón al aceite humeante. Guarda patatas y salsa separadas en la nevera a 4 °C o menos hasta 2 días; recalienta bien. La textura crujiente es mejor recién hecha.</p><h2>También puedes preparar</h2><ul><li><a href=\"/pizza-beans-alubias-gratinadas\">Pizza beans: alubias blancas con tomate y mozzarella</a></li><li><a href=\"/tartiflette-reblochon-patatas\">Tartiflette de patatas con reblochon y bacon</a></li></ul>","content_html":"<p>Patatas bravas doradas en freidora de aire, con salsa de pimentón y caldo sin tomate. Una tapa para compartir, con tiempos por tanda y picante ajustable.</p><p>Corta dados de 2 cm y usa una freidora de al menos 5 litros; si quedan amontonados, haz dos tandas y añade unos 25 minutos al total. La salsa lleva harina de trigo: contiene gluten. Usa caldo sin gluten y maicena solo con una adaptación de la salsa. No añadas el pimentón al aceite humeante. Guarda patatas y salsa separadas en la nevera a 4 °C o menos hasta 2 días; recalienta bien. La textura crujiente es mejor recién hecha.</p><h2>También puedes preparar</h2><ul><li><a href=\"/pizza-beans-alubias-gratinadas\">Pizza beans: alubias blancas con tomate y mozzarella</a></li><li><a href=\"/tartiflette-reblochon-patatas\">Tartiflette de patatas con reblochon y bacon</a></li></ul>","ingredients":[{"name":"patatas peladas","amount":"800","unit":"g"},{"name":"aceite de oliva: 15 g para patatas y 20 g para salsa","amount":"35","unit":"g"},{"name":"cebolla","amount":"100","unit":"g"},{"name":"ajo","amount":"5","unit":"g"},{"name":"harina de trigo","amount":"10","unit":"g"},{"name":"pimentón dulce","amount":"4","unit":"g"},{"name":"pimentón picante","amount":"1","unit":"g"},{"name":"caldo de verduras listo para usar","amount":"250","unit":"ml"},{"name":"vinagre de vino","amount":"10","unit":"ml"},{"name":"sal","amount":"3","unit":"g"}],"steps":[{"title":"Corta las patatas","content":"Pela 800 g de patatas y corta dados de 2 cm. Enjuaga y seca muy bien con un paño limpio; la humedad dificulta el dorado.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/patatas-bravas-freidora-aire/paso-01.webp","image_alt":"Patatas bravas en freidora de aire con salsa casera: Corta las patatas"},{"title":"Prepara la freidora","content":"Precalienta a 190 °C durante 3 minutos, si lo requiere el aparato. Mezcla las patatas con 15 g de aceite y 2 g de sal.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/patatas-bravas-freidora-aire/paso-02.webp","image_alt":"Patatas bravas en freidora de aire con salsa casera: Prepara la freidora"},{"title":"Cocina sin amontonar","content":"Extiende las patatas con espacio entre ellas. Cocina a 190 °C durante 20 minutos, agitando la cesta a mitad. Si no caben, haz dos tandas.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/patatas-bravas-freidora-aire/paso-03.webp","image_alt":"Patatas bravas en freidora de aire con salsa casera: Cocina sin amontonar"},{"title":"Pocha cebolla y ajo","content":"Mientras se cocinan, pica 100 g de cebolla y 5 g de ajo. Ablanda la cebolla con 20 g de aceite 8 minutos; añade el ajo 1 minuto.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/patatas-bravas-freidora-aire/paso-04.webp","image_alt":"Patatas bravas en freidora de aire con salsa casera: Pocha cebolla y ajo"},{"title":"Tuesta harina y pimentón","content":"Incorpora 10 g de harina y remueve 1 minuto. Aparta del fuego, añade ambos pimentones y mezcla unos segundos sin quemarlos.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/patatas-bravas-freidora-aire/paso-05.webp","image_alt":"Patatas bravas en freidora de aire con salsa casera: Tuesta harina y pimentón"},{"title":"Termina la salsa","content":"Añade poco a poco 250 ml de caldo, batiendo. Hierve suave 5 minutos; agrega vinagre y 1 g de sal. Tritura hasta obtener una salsa lisa.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/patatas-bravas-freidora-aire/paso-06.webp","image_alt":"Patatas bravas en freidora de aire con salsa casera: Termina la salsa"},{"title":"Comprueba el dorado","content":"Sube la freidora a 200 °C y cocina 3–5 minutos más. Las patatas deben estar tiernas por dentro y doradas por fuera; prolonga si hace falta.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/patatas-bravas-freidora-aire/paso-07.webp","image_alt":"Patatas bravas en freidora de aire con salsa casera: Comprueba el dorado"},{"title":"Sirve con la salsa","content":"Reparte en cuatro porciones de tapa y añade la salsa caliente justo antes de comer. Lleva la salsa sobrante a la mesa en un cuenco.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/patatas-bravas-freidora-aire/paso-08.webp","image_alt":"Patatas bravas en freidora de aire con salsa casera: Sirve con la salsa"}],"category":"Entrantes y aperitivos","course":"Entrantes y aperitivos","cuisine":"Española","difficulty":"Fácil","prep_time_minutes":15,"cook_time_minutes":35,"total_time_minutes":50,"servings":4,"image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/patatas-bravas-freidora-aire/portada.webp","gallery":[{"url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/patatas-bravas-freidora-aire/portada.webp","alt":"Patatas bravas en freidora de aire con salsa casera"}],"video_urls":[],"keywords":["Patatas bravas en freidora de aire con salsa casera","patatas peladas","aceite de oliva: 15 g para patatas y 20 g para salsa"],"nutrition":{"calories":259,"protein_g":5.0,"carbs_g":40.9,"fat_g":9.2,"saturated_fat_g":1.3,"fiber_g":5.2,"sugar_g":3.2,"sodium_mg":490.5,"estimated":true,"serving_size":"1 de 4 porciones","source":"USDA FoodData Central SR Legacy + reference product labels","source_url":"https://fdc.nal.usda.gov/","method":"Suma de referencias por peso, dividida entre las porciones; todos los ingredientes principales contabilizados.","note":"Estimación orientativa, no medición del plato cocinado. Las marcas y el escurrido cambian los valores; los nutrientes sin dato completo no se muestran."},"seo":{"title":"Patatas bravas en freidora de aire con salsa casera | Manual de Cocina","description":"Patatas bravas doradas en freidora de aire, con salsa de pimentón y caldo sin tomate. Una tapa para compartir, con tiempos por tanda y picante ajustable.","image_alt":"Patatas bravas en freidora de aire con salsa casera","image_variants":["https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/patatas-bravas-freidora-aire/portada-1x1.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/patatas-bravas-freidora-aire/portada-4x3.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/patatas-bravas-freidora-aire/portada-16x9.webp"],"faq":[{"q":"¿Se puede hacer sin tomate?","a":"Sí. Esta salsa se liga con harina y caldo y toma su color del pimentón; existen también otras versiones con tomate."},{"q":"¿Por qué quedan blandas?","a":"Suele haber exceso de humedad o demasiadas patatas en la cesta. Seca bien y cocina por tandas sin amontonar."},{"q":"¿Cómo reduzco el picante?","a":"Sustituye el gramo de pimentón picante por otro gramo de pimentón dulce. Mantén el resto de cantidades."}],"rest_time_minutes":0},"published":false,"editorial_status":"draft","source_url":null,"source_post_id":null,"recipe_group_id":"1f07d138-ca88-4c8c-8b40-f052f43b9134"},{"language":"de","slug":"patatas-bravas-heissluftfritteuse","public_path":"/de/patatas-bravas-heissluftfritteuse","title":"Patatas bravas aus der Heißluftfritteuse mit Paprikasauce","excerpt":"Goldbraune Kartoffelwürfel mit selbst gemachter Paprikasauce ohne Tomaten. Spanische Tapas mit einstellbarer Schärfe und Hinweisen zum Garen in Portionen.","summary":"Goldbraune Kartoffelwürfel mit selbst gemachter Paprikasauce ohne Tomaten. Spanische Tapas mit einstellbarer Schärfe und Hinweisen zum Garen in Portionen.","notes":"<p>2 cm große Würfel schneiden. Mindestens 5 Liter Korbvolumen verwenden; bei zwei Durchgängen etwa 25 Minuten zusätzlich einplanen. Enthält Weizen. Kartoffeln und Sauce getrennt bei höchstens 4 °C bis zu 2 Tage lagern und gründlich erhitzen. Sauce erst beim Servieren zugeben.</p><h2>Auch ausprobieren</h2><ul><li><a href=\"/de/pizza-bohnen-mozzarella\">Pizza Beans: weiße Bohnen mit Tomaten und Mozzarella</a></li><li><a href=\"/de/tartiflette-reblochon-kartoffeln\">Tartiflette mit Reblochon, Kartoffeln und Speck</a></li></ul>","content_html":"<p>Goldbraune Kartoffelwürfel mit selbst gemachter Paprikasauce ohne Tomaten. Spanische Tapas mit einstellbarer Schärfe und Hinweisen zum Garen in Portionen.</p><p>2 cm große Würfel schneiden. Mindestens 5 Liter Korbvolumen verwenden; bei zwei Durchgängen etwa 25 Minuten zusätzlich einplanen. Enthält Weizen. Kartoffeln und Sauce getrennt bei höchstens 4 °C bis zu 2 Tage lagern und gründlich erhitzen. Sauce erst beim Servieren zugeben.</p><h2>Auch ausprobieren</h2><ul><li><a href=\"/de/pizza-bohnen-mozzarella\">Pizza Beans: weiße Bohnen mit Tomaten und Mozzarella</a></li><li><a href=\"/de/tartiflette-reblochon-kartoffeln\">Tartiflette mit Reblochon, Kartoffeln und Speck</a></li></ul>","ingredients":[{"name":"geschälte Kartoffeln","amount":"800","unit":"g"},{"name":"Olivenöl: 15 g für Kartoffeln, 20 g für Sauce","amount":"35","unit":"g"},{"name":"Zwiebel","amount":"100","unit":"g"},{"name":"Knoblauch","amount":"5","unit":"g"},{"name":"Weizenmehl","amount":"10","unit":"g"},{"name":"edelsüßes Paprikapulver","amount":"4","unit":"g"},{"name":"scharfes Paprikapulver","amount":"1","unit":"g"},{"name":"gebrauchsfertige Gemüsebrühe","amount":"250","unit":"ml"},{"name":"Weinessig","amount":"10","unit":"ml"},{"name":"Salz","amount":"3","unit":"g"}],"steps":[{"title":"Kartoffeln schneiden","content":"800 g geschälte Kartoffeln in 2 cm große Würfel schneiden. Abspülen und mit einem sauberen Tuch gründlich trocknen.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/patatas-bravas-freidora-aire/paso-01.webp","image_alt":"Patatas bravas aus der Heißluftfritteuse mit Paprikasauce: Kartoffeln schneiden"},{"title":"Gerät vorbereiten","content":"Falls vom Hersteller empfohlen, 3 Minuten auf 190 °C vorheizen. Kartoffeln mit 15 g Öl und 2 g Salz mischen.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/patatas-bravas-freidora-aire/paso-02.webp","image_alt":"Patatas bravas aus der Heißluftfritteuse mit Paprikasauce: Gerät vorbereiten"},{"title":"Locker garen","content":"Mit etwas Abstand im Korb verteilen. Bei 190 °C 20 Minuten garen, nach der Hälfte schütteln. Bei Bedarf in zwei Durchgängen arbeiten.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/patatas-bravas-freidora-aire/paso-03.webp","image_alt":"Patatas bravas aus der Heißluftfritteuse mit Paprikasauce: Locker garen"},{"title":"Zwiebel und Knoblauch dünsten","content":"Beides fein hacken. Zwiebel in 20 g Öl 8 Minuten weich dünsten, Knoblauch 1 Minute mitdünsten.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/patatas-bravas-freidora-aire/paso-04.webp","image_alt":"Patatas bravas aus der Heißluftfritteuse mit Paprikasauce: Zwiebel und Knoblauch dünsten"},{"title":"Mehl und Paprika zugeben","content":"10 g Mehl 1 Minute unterrühren. Vom Herd nehmen, beide Paprikasorten kurz einrühren und nicht verbrennen lassen.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/patatas-bravas-freidora-aire/paso-05.webp","image_alt":"Patatas bravas aus der Heißluftfritteuse mit Paprikasauce: Mehl und Paprika zugeben"},{"title":"Sauce fertigstellen","content":"250 ml Brühe nach und nach einrühren. 5 Minuten sanft kochen, Essig und 1 g Salz zugeben und glatt pürieren.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/patatas-bravas-freidora-aire/paso-06.webp","image_alt":"Patatas bravas aus der Heißluftfritteuse mit Paprikasauce: Sauce fertigstellen"},{"title":"Bräunung prüfen","content":"Temperatur auf 200 °C erhöhen und weitere 3–5 Minuten garen. Die Kartoffeln sollen innen weich und außen goldbraun sein; nötigenfalls länger garen.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/patatas-bravas-freidora-aire/paso-07.webp","image_alt":"Patatas bravas aus der Heißluftfritteuse mit Paprikasauce: Bräunung prüfen"},{"title":"Mit Sauce servieren","content":"Auf vier Tapasportionen verteilen. Heiße Sauce erst unmittelbar vor dem Essen darübergeben, den Rest getrennt reichen.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/patatas-bravas-freidora-aire/paso-08.webp","image_alt":"Patatas bravas aus der Heißluftfritteuse mit Paprikasauce: Mit Sauce servieren"}],"category":"Vorspeisen","course":"Vorspeisen","cuisine":"Spanisch","difficulty":"Einfach","prep_time_minutes":15,"cook_time_minutes":35,"total_time_minutes":50,"servings":4,"image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/patatas-bravas-freidora-aire/portada.webp","gallery":[{"url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/patatas-bravas-freidora-aire/portada.webp","alt":"Patatas bravas aus der Heißluftfritteuse mit Paprikasauce"}],"video_urls":[],"keywords":["Patatas bravas aus der Heißluftfritteuse mit Paprikasauce","geschälte Kartoffeln","Olivenöl: 15 g für Kartoffeln, 20 g für Sauce"],"nutrition":{"calories":259,"protein_g":5.0,"carbs_g":40.9,"fat_g":9.2,"saturated_fat_g":1.3,"fiber_g":5.2,"sugar_g":3.2,"sodium_mg":490.5,"estimated":true,"serving_size":"1 von 4 Portionen","source":"USDA FoodData Central SR Legacy + reference product labels","source_url":"https://fdc.nal.usda.gov/","method":"Referenzwerte nach Zutatengewicht summiert und durch die Portionen geteilt.","note":"Ungefähre Schätzung, keine Messung des fertigen Gerichts. Marken und Abtropfen verändern die Werte; unvollständige Nährstoffdaten werden nicht angezeigt."},"seo":{"title":"Patatas bravas aus der Heißluftfritteuse mit Paprikasauce","description":"Goldbraune Kartoffelwürfel mit selbst gemachter Paprikasauce ohne Tomaten. Spanische Tapas mit einstellbarer Schärfe und Hinweisen zum Garen in Portionen.","image_alt":"Patatas bravas aus der Heißluftfritteuse mit Paprikasauce","image_variants":["https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/patatas-bravas-freidora-aire/portada-1x1.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/patatas-bravas-freidora-aire/portada-4x3.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/patatas-bravas-freidora-aire/portada-16x9.webp"],"faq":[{"q":"Braucht die Sauce Tomaten?","a":"Diese Variante nicht: Mehl und Brühe binden, Paprika färbt. Andere Varianten enthalten Tomaten."},{"q":"Warum werden die Kartoffeln weich?","a":"Feuchte Oberflächen oder ein voller Korb verhindern die Bräunung. Gründlich trocknen und portionsweise garen."},{"q":"Wie wird es milder?","a":"1 g scharfe Paprika durch zusätzlich 1 g edelsüße Paprika ersetzen."}],"rest_time_minutes":0},"published":false,"editorial_status":"draft","source_url":null,"source_post_id":null,"recipe_group_id":"1f07d138-ca88-4c8c-8b40-f052f43b9134"},{"language":"en","slug":"air-fryer-patatas-bravas","public_path":"/en/air-fryer-patatas-bravas","title":"Air fryer patatas bravas with homemade paprika sauce","excerpt":"Golden air fryer potatoes with a smooth, tomato-free paprika sauce. A Spanish sharing tapa with batch-cooking guidance and adjustable heat.","summary":"Golden air fryer potatoes with a smooth, tomato-free paprika sauce. A Spanish sharing tapa with batch-cooking guidance and adjustable heat.","notes":"<p>Cut 2 cm cubes. Use an air fryer of at least 5 litres; allow about 25 extra minutes for a second batch if crowded. Contains wheat. Keep potatoes and sauce separately at 4 °C or below for up to 2 days and reheat thoroughly. Add sauce just before serving.</p><h2>You may also like</h2><ul><li><a href=\"/en/pizza-beans\">Pizza beans with tomato and mozzarella</a></li><li><a href=\"/en/reblochon-tartiflette\">Reblochon tartiflette with potatoes and bacon</a></li></ul>","content_html":"<p>Golden air fryer potatoes with a smooth, tomato-free paprika sauce. A Spanish sharing tapa with batch-cooking guidance and adjustable heat.</p><p>Cut 2 cm cubes. Use an air fryer of at least 5 litres; allow about 25 extra minutes for a second batch if crowded. Contains wheat. Keep potatoes and sauce separately at 4 °C or below for up to 2 days and reheat thoroughly. Add sauce just before serving.</p><h2>You may also like</h2><ul><li><a href=\"/en/pizza-beans\">Pizza beans with tomato and mozzarella</a></li><li><a href=\"/en/reblochon-tartiflette\">Reblochon tartiflette with potatoes and bacon</a></li></ul>","ingredients":[{"name":"peeled potatoes","amount":"800","unit":"g"},{"name":"olive oil: 15 g for potatoes, 20 g for sauce","amount":"35","unit":"g"},{"name":"onion","amount":"100","unit":"g"},{"name":"garlic","amount":"5","unit":"g"},{"name":"plain all-purpose wheat flour","amount":"10","unit":"g"},{"name":"sweet paprika","amount":"4","unit":"g"},{"name":"hot paprika","amount":"1","unit":"g"},{"name":"ready-to-use vegetable stock","amount":"250","unit":"ml"},{"name":"wine vinegar","amount":"10","unit":"ml"},{"name":"salt","amount":"3","unit":"g"}],"steps":[{"title":"Cut the potatoes","content":"Cut 800 g peeled potatoes into 2 cm cubes. Rinse and dry thoroughly with a clean towel so the surfaces can brown.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/patatas-bravas-freidora-aire/paso-01.webp","image_alt":"Air fryer patatas bravas with homemade paprika sauce: Cut the potatoes"},{"title":"Prepare the air fryer","content":"Preheat to 190 °C for 3 minutes if required by your appliance. Toss potatoes with 15 g oil and 2 g salt.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/patatas-bravas-freidora-aire/paso-02.webp","image_alt":"Air fryer patatas bravas with homemade paprika sauce: Prepare the air fryer"},{"title":"Cook without crowding","content":"Spread potatoes with space around them. Cook at 190 °C for 20 minutes, shaking halfway through. Use two batches if necessary.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/patatas-bravas-freidora-aire/paso-03.webp","image_alt":"Air fryer patatas bravas with homemade paprika sauce: Cook without crowding"},{"title":"Soften onion and garlic","content":"Meanwhile, chop onion and garlic. Soften the onion in 20 g oil for 8 minutes, then add garlic for 1 minute.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/patatas-bravas-freidora-aire/paso-04.webp","image_alt":"Air fryer patatas bravas with homemade paprika sauce: Soften onion and garlic"},{"title":"Cook flour and paprika","content":"Stir in 10 g flour for 1 minute. Remove from the heat, add both paprikas and stir briefly without scorching.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/patatas-bravas-freidora-aire/paso-05.webp","image_alt":"Air fryer patatas bravas with homemade paprika sauce: Cook flour and paprika"},{"title":"Finish the sauce","content":"Gradually whisk in 250 ml stock. Simmer 5 minutes, add vinegar and 1 g salt, then blend until smooth.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/patatas-bravas-freidora-aire/paso-06.webp","image_alt":"Air fryer patatas bravas with homemade paprika sauce: Finish the sauce"},{"title":"Check the potatoes","content":"Increase to 200 °C and cook for another 3–5 minutes. Check for tender centres and golden edges; extend cooking if needed.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/patatas-bravas-freidora-aire/paso-07.webp","image_alt":"Air fryer patatas bravas with homemade paprika sauce: Check the potatoes"},{"title":"Serve with sauce","content":"Divide into four tapa portions. Spoon hot sauce over just before eating and serve any remaining sauce separately.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/patatas-bravas-freidora-aire/paso-08.webp","image_alt":"Air fryer patatas bravas with homemade paprika sauce: Serve with sauce"}],"category":"Starters & appetizers","course":"Starters & appetizers","cuisine":"Spanish","difficulty":"Easy","prep_time_minutes":15,"cook_time_minutes":35,"total_time_minutes":50,"servings":4,"image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/patatas-bravas-freidora-aire/portada.webp","gallery":[{"url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/patatas-bravas-freidora-aire/portada.webp","alt":"Air fryer patatas bravas with homemade paprika sauce"}],"video_urls":[],"keywords":["Air fryer patatas bravas with homemade paprika sauce","peeled potatoes","olive oil: 15 g for potatoes, 20 g for sauce"],"nutrition":{"calories":259,"protein_g":5.0,"carbs_g":40.9,"fat_g":9.2,"saturated_fat_g":1.3,"fiber_g":5.2,"sugar_g":3.2,"sodium_mg":490.5,"estimated":true,"serving_size":"1 of 4 servings","source":"USDA FoodData Central SR Legacy + reference product labels","source_url":"https://fdc.nal.usda.gov/","method":"Reference nutrients summed by ingredient weight and divided by servings.","note":"Approximate estimate, not a measurement of the cooked dish. Brands and draining change values; nutrients with incomplete data are omitted."},"seo":{"title":"Air fryer patatas bravas with homemade paprika sauce | Manual de Cocina","description":"Golden air fryer potatoes with a smooth, tomato-free paprika sauce. A Spanish sharing tapa with batch-cooking guidance and adjustable heat.","image_alt":"Air fryer patatas bravas with homemade paprika sauce","image_variants":["https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/patatas-bravas-freidora-aire/portada-1x1.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/patatas-bravas-freidora-aire/portada-4x3.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/patatas-bravas-freidora-aire/portada-16x9.webp"],"faq":[{"q":"Does bravas sauce need tomatoes?","a":"Not this version: flour and stock thicken it, while paprika gives colour. Other versions include tomatoes."},{"q":"Why are my potatoes soft?","a":"Excess moisture or a crowded basket prevents browning. Dry thoroughly and cook in batches."},{"q":"How do I reduce the heat?","a":"Replace the 1 g hot paprika with another 1 g sweet paprika."}],"rest_time_minutes":0},"published":false,"editorial_status":"draft","source_url":null,"source_post_id":null,"recipe_group_id":"1f07d138-ca88-4c8c-8b40-f052f43b9134"},{"language":"fr","slug":"patatas-bravas-airfryer","public_path":"/fr/patatas-bravas-airfryer","title":"Patatas bravas à l’air fryer et sauce paprika maison","excerpt":"Des pommes de terre dorées à l’air fryer, avec une sauce au paprika sans tomate. Une tapa espagnole à partager, avec un piquant facile à ajuster.","summary":"Des pommes de terre dorées à l’air fryer, avec une sauce au paprika sans tomate. Une tapa espagnole à partager, avec un piquant facile à ajuster.","notes":"<p>Coupez des cubes de 2 cm. Prévoyez un appareil d’au moins 5 litres et environ 25 minutes supplémentaires pour une seconde fournée si nécessaire. Contient du blé. Conservez pommes de terre et sauce séparément à 4 °C maximum pendant 2 jours et réchauffez à cœur. Saucez au dernier moment.</p><h2>À préparer aussi</h2><ul><li><a href=\"/fr/pizza-beans-haricots-mozzarella\">Pizza beans : haricots blancs, tomate et mozzarella</a></li><li><a href=\"/fr/tartiflette-reblochon\">Tartiflette au reblochon, pommes de terre et lardons</a></li></ul>","content_html":"<p>Des pommes de terre dorées à l’air fryer, avec une sauce au paprika sans tomate. Une tapa espagnole à partager, avec un piquant facile à ajuster.</p><p>Coupez des cubes de 2 cm. Prévoyez un appareil d’au moins 5 litres et environ 25 minutes supplémentaires pour une seconde fournée si nécessaire. Contient du blé. Conservez pommes de terre et sauce séparément à 4 °C maximum pendant 2 jours et réchauffez à cœur. Saucez au dernier moment.</p><h2>À préparer aussi</h2><ul><li><a href=\"/fr/pizza-beans-haricots-mozzarella\">Pizza beans : haricots blancs, tomate et mozzarella</a></li><li><a href=\"/fr/tartiflette-reblochon\">Tartiflette au reblochon, pommes de terre et lardons</a></li></ul>","ingredients":[{"name":"pommes de terre épluchées","amount":"800","unit":"g"},{"name":"huile d’olive : 15 g pour les pommes de terre, 20 g pour la sauce","amount":"35","unit":"g"},{"name":"oignon","amount":"100","unit":"g"},{"name":"ail","amount":"5","unit":"g"},{"name":"farine de blé","amount":"10","unit":"g"},{"name":"paprika doux","amount":"4","unit":"g"},{"name":"paprika fort","amount":"1","unit":"g"},{"name":"bouillon de légumes prêt à l’emploi","amount":"250","unit":"ml"},{"name":"vinaigre de vin","amount":"10","unit":"ml"},{"name":"sel","amount":"3","unit":"g"}],"steps":[{"title":"Coupez les pommes de terre","content":"Détaillez 800 g de pommes de terre en cubes de 2 cm. Rincez et séchez soigneusement avec un linge propre.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/patatas-bravas-freidora-aire/paso-01.webp","image_alt":"Patatas bravas à l’air fryer et sauce paprika maison: Coupez les pommes de terre"},{"title":"Préparez l’appareil","content":"Préchauffez à 190 °C pendant 3 minutes si le fabricant le demande. Mélangez les pommes de terre avec 15 g d’huile et 2 g de sel.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/patatas-bravas-freidora-aire/paso-02.webp","image_alt":"Patatas bravas à l’air fryer et sauce paprika maison: Préparez l’appareil"},{"title":"Cuisez sans entasser","content":"Répartissez en laissant de l’espace. Faites cuire 20 minutes à 190 °C, en secouant à mi-cuisson. Procédez en deux fournées si nécessaire.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/patatas-bravas-freidora-aire/paso-03.webp","image_alt":"Patatas bravas à l’air fryer et sauce paprika maison: Cuisez sans entasser"},{"title":"Faites fondre oignon et ail","content":"Hachez les deux. Faites fondre l’oignon dans 20 g d’huile pendant 8 minutes, puis ajoutez l’ail pour 1 minute.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/patatas-bravas-freidora-aire/paso-04.webp","image_alt":"Patatas bravas à l’air fryer et sauce paprika maison: Faites fondre oignon et ail"},{"title":"Ajoutez farine et paprika","content":"Incorporez 10 g de farine et remuez 1 minute. Hors du feu, ajoutez les deux paprikas et mélangez brièvement sans les brûler.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/patatas-bravas-freidora-aire/paso-05.webp","image_alt":"Patatas bravas à l’air fryer et sauce paprika maison: Ajoutez farine et paprika"},{"title":"Terminez la sauce","content":"Versez progressivement 250 ml de bouillon en fouettant. Laissez frémir 5 minutes, ajoutez vinaigre et 1 g de sel, puis mixez.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/patatas-bravas-freidora-aire/paso-06.webp","image_alt":"Patatas bravas à l’air fryer et sauce paprika maison: Terminez la sauce"},{"title":"Vérifiez la coloration","content":"Passez à 200 °C pour 3–5 minutes. Les cubes doivent être tendres au centre et dorés dehors ; prolongez au besoin.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/patatas-bravas-freidora-aire/paso-07.webp","image_alt":"Patatas bravas à l’air fryer et sauce paprika maison: Vérifiez la coloration"},{"title":"Servez avec la sauce","content":"Répartissez en quatre portions de tapas. Ajoutez la sauce chaude juste avant de manger et présentez le reste à part.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/patatas-bravas-freidora-aire/paso-08.webp","image_alt":"Patatas bravas à l’air fryer et sauce paprika maison: Servez avec la sauce"}],"category":"Entrées et apéritifs","course":"Entrées et apéritifs","cuisine":"Espagnole","difficulty":"Facile","prep_time_minutes":15,"cook_time_minutes":35,"total_time_minutes":50,"servings":4,"image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/patatas-bravas-freidora-aire/portada.webp","gallery":[{"url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/patatas-bravas-freidora-aire/portada.webp","alt":"Patatas bravas à l’air fryer et sauce paprika maison"}],"video_urls":[],"keywords":["Patatas bravas à l’air fryer et sauce paprika maison","pommes de terre épluchées","huile d’olive : 15 g pour les pommes de terre, 20 g pour la sauce"],"nutrition":{"calories":259,"protein_g":5.0,"carbs_g":40.9,"fat_g":9.2,"saturated_fat_g":1.3,"fiber_g":5.2,"sugar_g":3.2,"sodium_mg":490.5,"estimated":true,"serving_size":"1 des 4 portions","source":"USDA FoodData Central SR Legacy + reference product labels","source_url":"https://fdc.nal.usda.gov/","method":"Somme des références selon le poids des ingrédients, divisée par le nombre de portions.","note":"Estimation indicative, pas une mesure du plat cuisiné. Marques et égouttage changent les valeurs ; les nutriments incomplets ne sont pas affichés."},"seo":{"title":"Patatas bravas à l’air fryer et sauce paprika maison | Manual de Cocina","description":"Des pommes de terre dorées à l’air fryer, avec une sauce au paprika sans tomate. Une tapa espagnole à partager, avec un piquant facile à ajuster.","image_alt":"Patatas bravas à l’air fryer et sauce paprika maison","image_variants":["https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/patatas-bravas-freidora-aire/portada-1x1.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/patatas-bravas-freidora-aire/portada-4x3.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/patatas-bravas-freidora-aire/portada-16x9.webp"],"faq":[{"q":"Faut-il de la tomate ?","a":"Pas dans cette version : farine et bouillon lient la sauce, le paprika la colore. D’autres versions contiennent de la tomate."},{"q":"Pourquoi les cubes restent-ils mous ?","a":"L’humidité ou un panier trop rempli empêchent de dorer. Séchez bien et cuisez en plusieurs fournées."},{"q":"Comment diminuer le piquant ?","a":"Remplacez 1 g de paprika fort par 1 g supplémentaire de paprika doux."}],"rest_time_minutes":0},"published":false,"editorial_status":"draft","source_url":null,"source_post_id":null,"recipe_group_id":"1f07d138-ca88-4c8c-8b40-f052f43b9134"},{"language":"it","slug":"patatas-bravas-friggitrice-aria","public_path":"/it/patatas-bravas-friggitrice-aria","title":"Patatas bravas in friggitrice ad aria con salsa alla paprika","excerpt":"Patate dorate in friggitrice ad aria con salsa casalinga alla paprika, senza pomodoro. Una tapa spagnola da condividere, con piccantezza regolabile.","summary":"Patate dorate in friggitrice ad aria con salsa casalinga alla paprika, senza pomodoro. Una tapa spagnola da condividere, con piccantezza regolabile.","notes":"<p>Taglia cubetti di 2 cm. Usa una friggitrice da almeno 5 litri; per due turni considera circa 25 minuti in più. Contiene frumento. Conserva patate e salsa separate a 4 °C o meno fino a 2 giorni e riscalda bene. Condisci solo al momento di servire.</p><h2>Da provare anche</h2><ul><li><a href=\"/it/pizza-beans-fagioli-mozzarella\">Pizza beans: fagioli bianchi al pomodoro e mozzarella</a></li><li><a href=\"/it/tartiflette-reblochon-patate\">Tartiflette con patate, reblochon e pancetta affumicata</a></li></ul>","content_html":"<p>Patate dorate in friggitrice ad aria con salsa casalinga alla paprika, senza pomodoro. Una tapa spagnola da condividere, con piccantezza regolabile.</p><p>Taglia cubetti di 2 cm. Usa una friggitrice da almeno 5 litri; per due turni considera circa 25 minuti in più. Contiene frumento. Conserva patate e salsa separate a 4 °C o meno fino a 2 giorni e riscalda bene. Condisci solo al momento di servire.</p><h2>Da provare anche</h2><ul><li><a href=\"/it/pizza-beans-fagioli-mozzarella\">Pizza beans: fagioli bianchi al pomodoro e mozzarella</a></li><li><a href=\"/it/tartiflette-reblochon-patate\">Tartiflette con patate, reblochon e pancetta affumicata</a></li></ul>","ingredients":[{"name":"patate sbucciate","amount":"800","unit":"g"},{"name":"olio d’oliva: 15 g per le patate, 20 g per la salsa","amount":"35","unit":"g"},{"name":"cipolla","amount":"100","unit":"g"},{"name":"aglio","amount":"5","unit":"g"},{"name":"farina di frumento","amount":"10","unit":"g"},{"name":"paprika dolce","amount":"4","unit":"g"},{"name":"paprika piccante","amount":"1","unit":"g"},{"name":"brodo vegetale pronto","amount":"250","unit":"ml"},{"name":"aceto di vino","amount":"10","unit":"ml"},{"name":"sale","amount":"3","unit":"g"}],"steps":[{"title":"Taglia le patate","content":"Taglia 800 g di patate a cubetti di 2 cm. Sciacqua e asciuga molto bene con un canovaccio pulito.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/patatas-bravas-freidora-aire/paso-01.webp","image_alt":"Patatas bravas in friggitrice ad aria con salsa alla paprika: Taglia le patate"},{"title":"Prepara la friggitrice","content":"Se previsto dal produttore, preriscalda a 190 °C per 3 minuti. Mescola le patate con 15 g d’olio e 2 g di sale.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/patatas-bravas-freidora-aire/paso-02.webp","image_alt":"Patatas bravas in friggitrice ad aria con salsa alla paprika: Prepara la friggitrice"},{"title":"Cuoci senza ammassare","content":"Disponi lasciando spazio. Cuoci a 190 °C per 20 minuti, scuotendo a metà. Se necessario procedi in due turni.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/patatas-bravas-freidora-aire/paso-03.webp","image_alt":"Patatas bravas in friggitrice ad aria con salsa alla paprika: Cuoci senza ammassare"},{"title":"Ammorbidisci cipolla e aglio","content":"Trita entrambi. Cuoci la cipolla con 20 g d’olio per 8 minuti, poi aggiungi l’aglio per 1 minuto.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/patatas-bravas-freidora-aire/paso-04.webp","image_alt":"Patatas bravas in friggitrice ad aria con salsa alla paprika: Ammorbidisci cipolla e aglio"},{"title":"Aggiungi farina e paprika","content":"Mescola 10 g di farina per 1 minuto. Fuori dal fuoco incorpora le due paprike per pochi secondi senza bruciarle.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/patatas-bravas-freidora-aire/paso-05.webp","image_alt":"Patatas bravas in friggitrice ad aria con salsa alla paprika: Aggiungi farina e paprika"},{"title":"Completa la salsa","content":"Versa gradualmente 250 ml di brodo mescolando con una frusta. Fai sobbollire 5 minuti, aggiungi aceto e 1 g di sale, poi frulla.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/patatas-bravas-freidora-aire/paso-06.webp","image_alt":"Patatas bravas in friggitrice ad aria con salsa alla paprika: Completa la salsa"},{"title":"Controlla la doratura","content":"Porta a 200 °C e cuoci ancora 3–5 minuti. Le patate devono essere tenere dentro e dorate fuori; prolunga se necessario.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/patatas-bravas-freidora-aire/paso-07.webp","image_alt":"Patatas bravas in friggitrice ad aria con salsa alla paprika: Controlla la doratura"},{"title":"Servi con la salsa","content":"Dividi in quattro porzioni da aperitivo. Versa la salsa calda solo prima di mangiare e servi quella rimasta a parte.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/patatas-bravas-freidora-aire/paso-08.webp","image_alt":"Patatas bravas in friggitrice ad aria con salsa alla paprika: Servi con la salsa"}],"category":"Antipasti","course":"Antipasti","cuisine":"Spagnola","difficulty":"Facile","prep_time_minutes":15,"cook_time_minutes":35,"total_time_minutes":50,"servings":4,"image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/patatas-bravas-freidora-aire/portada.webp","gallery":[{"url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/patatas-bravas-freidora-aire/portada.webp","alt":"Patatas bravas in friggitrice ad aria con salsa alla paprika"}],"video_urls":[],"keywords":["Patatas bravas in friggitrice ad aria con salsa alla paprika","patate sbucciate","olio d’oliva: 15 g per le patate, 20 g per la salsa"],"nutrition":{"calories":259,"protein_g":5.0,"carbs_g":40.9,"fat_g":9.2,"saturated_fat_g":1.3,"fiber_g":5.2,"sugar_g":3.2,"sodium_mg":490.5,"estimated":true,"serving_size":"1 di 4 porzioni","source":"USDA FoodData Central SR Legacy + reference product labels","source_url":"https://fdc.nal.usda.gov/","method":"Somma dei valori di riferimento per peso, divisa per le porzioni.","note":"Stima indicativa, non misurazione del piatto cotto. Marche e scolatura modificano i valori; nutrienti con dati incompleti non sono mostrati."},"seo":{"title":"Patatas bravas in friggitrice ad aria con salsa alla paprika","description":"Patate dorate in friggitrice ad aria con salsa casalinga alla paprika, senza pomodoro. Una tapa spagnola da condividere, con piccantezza regolabile.","image_alt":"Patatas bravas in friggitrice ad aria con salsa alla paprika","image_variants":["https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/patatas-bravas-freidora-aire/portada-1x1.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/patatas-bravas-freidora-aire/portada-4x3.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/patatas-bravas-freidora-aire/portada-16x9.webp"],"faq":[{"q":"Serve il pomodoro?","a":"Non in questa versione: farina e brodo addensano, la paprika colora. Esistono anche varianti al pomodoro."},{"q":"Perché rimangono morbide?","a":"Umidità e cestello pieno impediscono la doratura. Asciuga bene e cuoci in più turni."},{"q":"Come riduco il piccante?","a":"Sostituisci 1 g di paprika piccante con un altro grammo di paprika dolce."}],"rest_time_minutes":0},"published":false,"editorial_status":"draft","source_url":null,"source_post_id":null,"recipe_group_id":"1f07d138-ca88-4c8c-8b40-f052f43b9134"},{"language":"ja","slug":"air-fryer-patatas-bravas","public_path":"/ja/air-fryer-patatas-bravas","title":"エアフライヤーで作るパタタス・ブラバス","excerpt":"角切りじゃがいもをエアフライヤーで香ばしく焼き、トマトを使わないパプリカソースを添えるスペイン風おつまみ。辛さと分け焼きの目安も紹介します。","summary":"角切りじゃがいもをエアフライヤーで香ばしく焼き、トマトを使わないパプリカソースを添えるスペイン風おつまみ。辛さと分け焼きの目安も紹介します。","notes":"<p>じゃがいもは2 cm角に切ります。容量5 L以上が目安で、2回に分ける場合は約25分追加してください。小麦を含みます。残りはソースと分けて4 °C以下で冷蔵し、2日以内に十分温め直して食べます。ソースは食べる直前にかけます。</p><h2>こちらのレシピも</h2><ul><li><a href=\"/ja/pizza-beans\">ピザビーンズ：白いんげん豆のトマトチーズ焼き</a></li><li><a href=\"/ja/reblochon-tartiflette\">ルブロションのタルティフレット</a></li></ul>","content_html":"<p>角切りじゃがいもをエアフライヤーで香ばしく焼き、トマトを使わないパプリカソースを添えるスペイン風おつまみ。辛さと分け焼きの目安も紹介します。</p><p>じゃがいもは2 cm角に切ります。容量5 L以上が目安で、2回に分ける場合は約25分追加してください。小麦を含みます。残りはソースと分けて4 °C以下で冷蔵し、2日以内に十分温め直して食べます。ソースは食べる直前にかけます。</p><h2>こちらのレシピも</h2><ul><li><a href=\"/ja/pizza-beans\">ピザビーンズ：白いんげん豆のトマトチーズ焼き</a></li><li><a href=\"/ja/reblochon-tartiflette\">ルブロションのタルティフレット</a></li></ul>","ingredients":[{"name":"皮をむいたじゃがいも","amount":"800","unit":"g"},{"name":"オリーブオイル：じゃがいも用15 g、ソース用20 g","amount":"35","unit":"g"},{"name":"玉ねぎ","amount":"100","unit":"g"},{"name":"にんにく","amount":"5","unit":"g"},{"name":"小麦粉","amount":"10","unit":"g"},{"name":"辛くないパプリカパウダー","amount":"4","unit":"g"},{"name":"辛口パプリカパウダー","amount":"1","unit":"g"},{"name":"そのまま使える野菜ブイヨン","amount":"250","unit":"ml"},{"name":"ワインビネガー","amount":"10","unit":"ml"},{"name":"塩","amount":"3","unit":"g"}],"steps":[{"title":"じゃがいもを切る","content":"じゃがいも800 gを2 cm角に切ります。洗ってから清潔な布で水分をしっかり拭き取ります。","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/patatas-bravas-freidora-aire/paso-01.webp","image_alt":"エアフライヤーで作るパタタス・ブラバス: じゃがいもを切る"},{"title":"器具を準備する","content":"メーカーが推奨する場合は190 °Cで3分予熱します。じゃがいもに油15 gと塩2 gをまぶします。","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/patatas-bravas-freidora-aire/paso-02.webp","image_alt":"エアフライヤーで作るパタタス・ブラバス: 器具を準備する"},{"title":"重ねずに加熱する","content":"隙間をあけて並べ、190 °Cで20分加熱します。途中でかごを揺すり、入りきらなければ2回に分けます。","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/patatas-bravas-freidora-aire/paso-03.webp","image_alt":"エアフライヤーで作るパタタス・ブラバス: 重ねずに加熱する"},{"title":"玉ねぎとにんにくを炒める","content":"両方をみじん切りにします。油20 gで玉ねぎを8分炒め、にんにくを加えてさらに1分炒めます。","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/patatas-bravas-freidora-aire/paso-04.webp","image_alt":"エアフライヤーで作るパタタス・ブラバス: 玉ねぎとにんにくを炒める"},{"title":"小麦粉とパプリカを加える","content":"小麦粉10 gを加えて1分混ぜます。火から外し、2種類のパプリカを加えて焦がさず短く混ぜます。","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/patatas-bravas-freidora-aire/paso-05.webp","image_alt":"エアフライヤーで作るパタタス・ブラバス: 小麦粉とパプリカを加える"},{"title":"ソースを仕上げる","content":"ブイヨン250 mlを少しずつ加えながら混ぜます。弱く沸かして5分煮て、酢と塩1 gを加え、なめらかに攪拌します。","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/patatas-bravas-freidora-aire/paso-06.webp","image_alt":"エアフライヤーで作るパタタス・ブラバス: ソースを仕上げる"},{"title":"焼き色を確かめる","content":"200 °Cに上げてさらに3〜5分加熱します。中まで柔らかく、表面がきつね色になるまで必要に応じて延長します。","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/patatas-bravas-freidora-aire/paso-07.webp","image_alt":"エアフライヤーで作るパタタス・ブラバス: 焼き色を確かめる"},{"title":"ソースを添えて盛る","content":"おつまみ用に4等分します。温かいソースは食べる直前にかけ、余った分は別の器で添えます。","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/patatas-bravas-freidora-aire/paso-08.webp","image_alt":"エアフライヤーで作るパタタス・ブラバス: ソースを添えて盛る"}],"category":"前菜・おつまみ","course":"前菜・おつまみ","cuisine":"スペイン料理","difficulty":"簡単","prep_time_minutes":15,"cook_time_minutes":35,"total_time_minutes":50,"servings":4,"image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/patatas-bravas-freidora-aire/portada.webp","gallery":[{"url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/patatas-bravas-freidora-aire/portada.webp","alt":"エアフライヤーで作るパタタス・ブラバス"}],"video_urls":[],"keywords":["エアフライヤーで作るパタタス・ブラバス","皮をむいたじゃがいも","オリーブオイル：じゃがいも用15 g、ソース用20 g"],"nutrition":{"calories":259,"protein_g":5.0,"carbs_g":40.9,"fat_g":9.2,"saturated_fat_g":1.3,"fiber_g":5.2,"sugar_g":3.2,"sodium_mg":490.5,"estimated":true,"serving_size":"全4人分のうち1人分","source":"USDA FoodData Central SR Legacy + reference product labels","source_url":"https://fdc.nal.usda.gov/","method":"材料の重量に応じた参考栄養値を合計し、人数で割っています。","note":"調理済み料理の実測値ではなく概算です。商品や水切りで変わり、資料がそろわない栄養素は表示しません。"},"seo":{"title":"エアフライヤーで作るパタタス・ブラバス | Manual de Cocina","description":"角切りじゃがいもをエアフライヤーで香ばしく焼き、トマトを使わないパプリカソースを添えるスペイン風おつまみ。辛さと分け焼きの目安も紹介します。","image_alt":"エアフライヤーで作るパタタス・ブラバス","image_variants":["https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/patatas-bravas-freidora-aire/portada-1x1.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/patatas-bravas-freidora-aire/portada-4x3.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/patatas-bravas-freidora-aire/portada-16x9.webp"],"faq":[{"q":"トマトは必要ですか？","a":"この作り方では使いません。小麦粉とブイヨンでとろみをつけ、パプリカで色づけします。トマト入りの別の作り方もあります。"},{"q":"カリッとしないのはなぜ？","a":"水分が残っていたり、かごに詰めすぎたりすると焼き色がつきにくくなります。よく乾かして分けて焼きます。"},{"q":"辛さを抑えるには？","a":"辛口パプリカ1 gを、辛くないパプリカ1 gに置き換えます。"}],"rest_time_minutes":0},"published":false,"editorial_status":"draft","source_url":null,"source_post_id":null,"recipe_group_id":"1f07d138-ca88-4c8c-8b40-f052f43b9134"},{"language":"pt","slug":"batatas-bravas-airfryer","public_path":"/pt/batatas-bravas-airfryer","title":"Batatas bravas na air fryer com molho de páprica","excerpt":"Batatas douradas na air fryer com molho caseiro de páprica e caldo, sem tomate. Um petisco espanhol para compartilhar, com ardência ajustável.","summary":"Batatas douradas na air fryer com molho caseiro de páprica e caldo, sem tomate. Um petisco espanhol para compartilhar, com ardência ajustável.","notes":"<p>Corte cubos de 2 cm. Use air fryer de pelo menos 5 litros; se precisar de duas levas, acrescente cerca de 25 minutos. Contém trigo. Guarde batatas e molho separados a 4 °C ou menos por até 2 dias e reaqueça por completo. Coloque o molho só na hora de servir.</p><h2>Prepare também</h2><ul><li><a href=\"/pt/pizza-beans-feijao-mucarela\">Pizza beans: feijão branco com tomate e muçarela</a></li><li><a href=\"/pt/tartiflette-reblochon-batatas\">Tartiflette de batata com reblochon e bacon</a></li></ul>","content_html":"<p>Batatas douradas na air fryer com molho caseiro de páprica e caldo, sem tomate. Um petisco espanhol para compartilhar, com ardência ajustável.</p><p>Corte cubos de 2 cm. Use air fryer de pelo menos 5 litros; se precisar de duas levas, acrescente cerca de 25 minutos. Contém trigo. Guarde batatas e molho separados a 4 °C ou menos por até 2 dias e reaqueça por completo. Coloque o molho só na hora de servir.</p><h2>Prepare também</h2><ul><li><a href=\"/pt/pizza-beans-feijao-mucarela\">Pizza beans: feijão branco com tomate e muçarela</a></li><li><a href=\"/pt/tartiflette-reblochon-batatas\">Tartiflette de batata com reblochon e bacon</a></li></ul>","ingredients":[{"name":"batatas descascadas","amount":"800","unit":"g"},{"name":"azeite: 15 g para batatas e 20 g para molho","amount":"35","unit":"g"},{"name":"cebola","amount":"100","unit":"g"},{"name":"alho","amount":"5","unit":"g"},{"name":"farinha de trigo","amount":"10","unit":"g"},{"name":"páprica doce","amount":"4","unit":"g"},{"name":"páprica picante","amount":"1","unit":"g"},{"name":"caldo de legumes pronto para uso","amount":"250","unit":"ml"},{"name":"vinagre de vinho","amount":"10","unit":"ml"},{"name":"sal","amount":"3","unit":"g"}],"steps":[{"title":"Corte as batatas","content":"Corte 800 g de batatas em cubos de 2 cm. Enxágue e seque muito bem com um pano limpo.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/patatas-bravas-freidora-aire/paso-01.webp","image_alt":"Batatas bravas na air fryer com molho de páprica: Corte as batatas"},{"title":"Prepare a air fryer","content":"Se o fabricante recomendar, preaqueça a 190 °C por 3 minutos. Misture as batatas com 15 g de azeite e 2 g de sal.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/patatas-bravas-freidora-aire/paso-02.webp","image_alt":"Batatas bravas na air fryer com molho de páprica: Prepare a air fryer"},{"title":"Cozinhe sem amontoar","content":"Distribua deixando espaço. Asse a 190 °C por 20 minutos, sacudindo na metade. Faça duas levas se necessário.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/patatas-bravas-freidora-aire/paso-03.webp","image_alt":"Batatas bravas na air fryer com molho de páprica: Cozinhe sem amontoar"},{"title":"Refogue cebola e alho","content":"Pique ambos. Refogue a cebola em 20 g de azeite por 8 minutos e acrescente o alho por mais 1 minuto.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/patatas-bravas-freidora-aire/paso-04.webp","image_alt":"Batatas bravas na air fryer com molho de páprica: Refogue cebola e alho"},{"title":"Junte farinha e páprica","content":"Mexa 10 g de farinha por 1 minuto. Tire do fogo e misture as duas pápricas por alguns segundos sem queimar.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/patatas-bravas-freidora-aire/paso-05.webp","image_alt":"Batatas bravas na air fryer com molho de páprica: Junte farinha e páprica"},{"title":"Finalize o molho","content":"Adicione aos poucos 250 ml de caldo, mexendo com um batedor. Ferva suavemente 5 minutos, junte vinagre e 1 g de sal e bata até alisar.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/patatas-bravas-freidora-aire/paso-06.webp","image_alt":"Batatas bravas na air fryer com molho de páprica: Finalize o molho"},{"title":"Confira a cor","content":"Aumente para 200 °C e cozinhe mais 3–5 minutos. As batatas devem ficar macias por dentro e douradas por fora; prolongue se necessário.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/patatas-bravas-freidora-aire/paso-07.webp","image_alt":"Batatas bravas na air fryer com molho de páprica: Confira a cor"},{"title":"Sirva com molho","content":"Divida em quatro porções de petisco. Coloque o molho quente apenas antes de comer e sirva o restante separado.","image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/patatas-bravas-freidora-aire/paso-08.webp","image_alt":"Batatas bravas na air fryer com molho de páprica: Sirva com molho"}],"category":"Entradas e aperitivos","course":"Entradas e aperitivos","cuisine":"Espanhola","difficulty":"Fácil","prep_time_minutes":15,"cook_time_minutes":35,"total_time_minutes":50,"servings":4,"image_url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/patatas-bravas-freidora-aire/portada.webp","gallery":[{"url":"https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/patatas-bravas-freidora-aire/portada.webp","alt":"Batatas bravas na air fryer com molho de páprica"}],"video_urls":[],"keywords":["Batatas bravas na air fryer com molho de páprica","batatas descascadas","azeite: 15 g para batatas e 20 g para molho"],"nutrition":{"calories":259,"protein_g":5.0,"carbs_g":40.9,"fat_g":9.2,"saturated_fat_g":1.3,"fiber_g":5.2,"sugar_g":3.2,"sodium_mg":490.5,"estimated":true,"serving_size":"1 das 4 porções","source":"USDA FoodData Central SR Legacy + reference product labels","source_url":"https://fdc.nal.usda.gov/","method":"Soma das referências pelo peso dos ingredientes, dividida pelas porções.","note":"Estimativa orientativa, não medição do prato pronto. Marcas e escorrimento alteram os valores; nutrientes com dados incompletos não são mostrados."},"seo":{"title":"Batatas bravas na air fryer com molho de páprica | Manual de Cocina","description":"Batatas douradas na air fryer com molho caseiro de páprica e caldo, sem tomate. Um petisco espanhol para compartilhar, com ardência ajustável.","image_alt":"Batatas bravas na air fryer com molho de páprica","image_variants":["https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/patatas-bravas-freidora-aire/portada-1x1.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/patatas-bravas-freidora-aire/portada-4x3.webp","https://eqbdtctxbpepbeickhqi.supabase.co/storage/v1/object/public/recetas/patatas-bravas-freidora-aire/portada-16x9.webp"],"faq":[{"q":"Precisa de tomate?","a":"Nesta versão, não: farinha e caldo engrossam o molho e a páprica dá cor. Existem versões com tomate."},{"q":"Por que as batatas ficam moles?","a":"Umidade ou cesto cheio impedem dourar. Seque bem e cozinhe em levas."},{"q":"Como diminuir a ardência?","a":"Troque 1 g de páprica picante por mais 1 g de páprica doce."}],"rest_time_minutes":0},"published":false,"editorial_status":"draft","source_url":null,"source_post_id":null,"recipe_group_id":"1f07d138-ca88-4c8c-8b40-f052f43b9134"}]$expected$::jsonb; x jsonb; v public.recipes; n int:=0;
BEGIN
 IF jsonb_array_length(j)<>7 THEN RAISE EXCEPTION 'Expected 7 records'; END IF;
 IF (SELECT count(*) FROM public.recipes r JOIN jsonb_array_elements(j) e ON r.public_path=e->>'public_path' AND r.recipe_group_id=(e->>'recipe_group_id')::uuid AND r.language=e->>'language')<>7 THEN RAISE EXCEPTION 'Group identity mismatch'; END IF;
 FOR x IN SELECT value FROM jsonb_array_elements(j) LOOP
  SELECT * INTO STRICT v FROM public.recipes WHERE public_path=x->>'public_path' AND recipe_group_id=(x->>'recipe_group_id')::uuid FOR UPDATE;
  IF v.published OR v.title IS DISTINCT FROM x->>'title' OR v.ingredients IS DISTINCT FROM x->'ingredients' OR v.steps IS DISTINCT FROM x->'steps' OR v.nutrition IS DISTINCT FROM x->'nutrition' OR v.seo IS DISTINCT FROM x->'seo' OR v.image_url IS DISTINCT FROM x->>'image_url' OR v.content_html IS DISTINCT FROM x->>'content_html' OR v.total_time_minutes IS DISTINCT FROM (x->>'total_time_minutes')::int THEN RAISE EXCEPTION 'Draft changed or already published: %',v.public_path; END IF;
 END LOOP;
 PERFORM set_config('request.jwt.claim.sub','2caf0bab-d7e8-4d52-9910-d79799c27072',true);
 IF NOT public.is_admin() THEN RAISE EXCEPTION 'Missing admin context'; END IF;
 FOR x IN SELECT value FROM jsonb_array_elements(j) LOOP
  SELECT * INTO STRICT v FROM public.recipes WHERE public_path=x->>'public_path' AND recipe_group_id=(x->>'recipe_group_id')::uuid;
  UPDATE public.recipes SET editorial_status='ready',ready_at=now(),reviewed_at=now(),reviewed_by='Codex editorial QA, owner-authorized 2026-10-27' WHERE id=v.id;
  PERFORM public.update_recipe(v.id,v.slug,v.title,v.excerpt,v.ingredients,v.steps,v.category,v.prep_time_minutes,v.cook_time_minutes,v.servings,v.image_url,true);
  UPDATE public.recipes SET editorial_status='published',published_by='Codex owner-authorized siete mercados 2026-10-27' WHERE id=v.id;
  n:=n+1;
 END LOOP;
 IF n<>7 THEN RAISE EXCEPTION 'Expected 7 publications'; END IF;
END $publish$;
SELECT language,public_path,published FROM public.recipes WHERE recipe_group_id='1f07d138-ca88-4c8c-8b40-f052f43b9134' ORDER BY language;
